const r = $input.first()?.json || {};

if (r.error) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo eliminar la implementación: ' + (r.error?.message || r.error) } } }];
}

// Sin fila devuelta, o con la fila vacía que n8n produce cuando el DELETE no
// afectó a nadie: el id no existe.
if (!r.id) {
  return [{ json: { statusCode: 404, body: { message: 'La implementación no existe.' } } }];
}

// Las filas de hook_execution_log NO se borran: su registry_id queda en NULL por
// la FK (ON DELETE SET NULL) y el handler_ref desnormalizado deja constancia de
// qué corrió. La traza histórica sobrevive a la baja.
return [{ json: { statusCode: 200, body: r } }];
